INSERT INTO `projects` (`id`, `title_ua`, `title_en`, `category`, `description_ua`, `description_en`, `image`, `gallery`, `order_column`, `is_active`, `created_at`, `updated_at`) VALUES (1, '10kV Substation Busbar & Modular Insulator', '10kV Substation Busbar & Modular Insulator', 'industrial', 'Flame-retardant high-voltage dielectric busbar supports with internal aerodynamic ribbing to eliminate arc discharge under 10,000V live load.', 'Flame-retardant high-voltage dielectric busbar supports with internal aerodynamic ribbing to eliminate arc discharge under 10,000V live load.', 'images/zas.png', NULL, 1, 1, '2026-11-23 10:01:32', '2026-11-23 10:01:32');
INSERT INTO `projects` (`id`, `title_ua`, `title_en`, `category`, `description_ua`, `description_en`, `image`, `gallery`, `order_column`, `is_active`, `created_at`, `updated_at`) VALUES (2, 'Autonomous Tracked Rover with Robotic Manipulator', 'Autonomous Tracked Rover with Robotic Manipulator', 'robotics', 'End-to-end design from engineering sketch to functioning prototype: reinforced tracked chassis, 6-axis 3D-printed manipulator arm, custom gripper, and sensor payload.', 'End-to-end design from engineering sketch to functioning prototype: reinforced tracked chassis, 6-axis 3D-printed manipulator arm, custom gripper, and sensor payload.', 'images/zas2.png', NULL, 2, 1, '2026-11-23 10:01:32', '2026-11-23 10:01:32');
INSERT INTO `projects` (`id`, `title_ua`, `title_en`, `category`, `description_ua`, `description_en`, `image`, `gallery`, `order_column`, `is_active`, `created_at`, `updated_at`) VALUES (3, 'Full-Cycle Walking Robot (Draft to Assembly)', 'Full-Cycle Walking Robot (Draft to Assembly)', 'mechatronics', 'Modex 4-stage turnkey development: engineering math and hand drafting, parametric 3D CAD simulation, FDM 3D printing of joints, and electromechanical assembly.', 'Modex 4-stage turnkey development: engineering math and hand drafting, parametric 3D CAD simulation, FDM 3D printing of joints, and electromechanical assembly.', 'images/zas3.png', NULL, 3, 1, '2026-11-23 10:01:32', '2026-11-23 10:01:32');

